#!/usr/bin/env python3
import os, sys, json, time, threading, queue, uuid
from pathlib import Path
from datetime import datetime, timezone
import importlib.util
from http.server import ThreadingHTTPServer
from urllib.parse import urlparse

HERE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location("chat_lokal_base",HERE/"base_commander.py")
base=importlib.util.module_from_spec(spec); spec.loader.exec_module(base)

HOME=Path.home()/".copytolive-chat-lokal"
base.HOME=HOME
base.CONFIG=HOME/"config.json"
base.TOKEN_FILE=HOME/"token"
base.LOG_FILE=HOME/"chat-lokal.log"
base.SESSIONS=HOME/"sessions"
HOME.mkdir(parents=True,exist_ok=True)
base.SESSIONS.mkdir(parents=True,exist_ok=True)

def now():
    return datetime.now(timezone.utc).isoformat()

class ChatCommander(base.Commander):
    def init_db(self):
        self.pending=queue.Queue(maxsize=50000)
        self.state_lock=threading.RLock()
        self.requests={}
        self.results={}
        self.req_journal=HOME/"requests.jsonl"
        self.res_journal=HOME/"results.jsonl"
        for p in (self.req_journal,self.res_journal):
            p.touch(exist_ok=True)
        for line in self.req_journal.read_text(encoding="utf-8",errors="replace").splitlines():
            try:
                x=json.loads(line); self.requests[x["id"]]=x["request"]
            except Exception: pass
        for line in self.res_journal.read_text(encoding="utf-8",errors="replace").splitlines():
            try:
                x=json.loads(line); self.results[x["id"]]=x["result"]
            except Exception: pass
        for tid,req in list(self.requests.items()):
            if tid not in self.results:
                try:self.pending.put_nowait((tid,req))
                except queue.Full: break

    def _append(self,path,obj):
        raw=json.dumps(obj,ensure_ascii=False,separators=(",",":"))+"\n"
        with path.open("a",encoding="utf-8") as f:
            f.write(raw); f.flush()

    def enqueue(self,req):
        tid=req.get("id") or ("q-"+uuid.uuid4().hex)
        with self.state_lock:
            old=self.requests.get(tid)
            if old is not None:
                if old!=req: raise RuntimeError("task id collision with different payload")
                return tid
            self.requests[tid]=req
            self._append(self.req_journal,{"id":tid,"request":req,"at":now()})
            self.pending.put_nowait((tid,req))
        return tid

    def task_result(self,tid):
        with self.state_lock:
            if tid in self.results:
                r=self.results[tid]
                return {"id":tid,"status":"done" if r.get("ok") else "error","result":r}
            if tid in self.requests:
                return {"id":tid,"status":"queued","result":None}
        return None

    def finish(self,tid,result):
        with self.state_lock:
            self.results[tid]=result
            self._append(self.res_journal,{"id":tid,"result":result,"at":now()})

    def worker(self,n):
        base.log(f"chat-local worker {n} start")
        while True:
            try:
                tid,req=self.pending.get(timeout=.5)
            except queue.Empty:
                continue
            try:
                try:
                    data=self.execute(req)
                    ans={"ok":True,"id":tid,"data":data,"completed_at":now()}
                except Exception as e:
                    ans={"ok":False,"id":tid,"error":type(e).__name__,"message":str(e),"completed_at":now()}
                self.finish(tid,ans)
            except Exception as e:
                base.log(f"worker {n} persistence error {type(e).__name__}: {e}")
            finally:
                self.pending.task_done()

class ChatHTTPServer(base.CommanderHTTPServer):
    request_queue_size=2048
    daemon_threads=True
    allow_reuse_address=True

class Handler(base.Handler):
    server_version="CopyToLiveChatLokal/1.0"
    def do_GET(self):
        path=urlparse(self.path).path
        if path=="/health":
            c=self.server.commander
            return self.send_json(200,{
                "ok":True,"profile":"Chat - Lokal","transport":"127.0.0.1 only",
                "third_party":False,"github":False,"workers":c.workers,
                "queued":c.pending.qsize(),"time":now()
            })
        if path=="/v1/stats":
            if not self.auth(): return self.send_json(401,{"ok":False,"error":"Unauthorized"})
            c=self.server.commander
            with c.state_lock:
                return self.send_json(200,{"ok":True,"requests":len(c.requests),
                    "results":len(c.results),"queued":c.pending.qsize(),"workers":c.workers})
        return super().do_GET()

def serve():
    c=ChatCommander()
    for i in range(c.workers):
        threading.Thread(target=c.worker,args=(i,),daemon=True,name=f"chat-local-worker-{i}").start()
    srv=ChatHTTPServer(("127.0.0.1",c.port),Handler)
    srv.commander=c; srv.token=base.TOKEN_FILE.read_text(encoding='utf-8').strip()
    base.log(f"CHAT_LOKAL=ONLINE port={c.port} workers={c.workers} third_party=false")
    srv.serve_forever(poll_interval=.05)

if __name__=="__main__":
    serve()

